import{_ as e,a,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"程序员的数学","description":"以结城浩作者目录为参考，理解逻辑、归纳、递归和计算边界。","frontmatter":{"title":"程序员的数学","description":"以结城浩作者目录为参考，理解逻辑、归纳、递归和计算边界。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 数据结构、算法与软件设计","summary":"以结城浩作者目录为参考，理解逻辑、归纳、递归和计算边界。","status":"active","related":[{"title":"数据结构导论","link":"/life/personal/books/computing/data-structures","kind":"书籍导读","scope":"general","audience":"general"},{"title":"算法导论（原书第3版）","link":"/life/personal/books/computing/introduction-to-algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"漫画算法","link":"/life/personal/books/computing/comic-algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"重构 改善既有代码的设计（第2版）","link":"/life/personal/books/computing/refactoring","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms"},"next":{"text":"重构 改善既有代码的设计（第2版）","link":"/life/personal/books/computing/refactoring"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms"},"next":{"text":"重构 改善既有代码的设计（第2版）","link":"/life/personal/books/computing/refactoring"}},"headers":[],"relativePath":"life/personal/books/computing/programmers-math.md","filePath":"life/personal/books/computing/programmers-math.md"}'),i={name:"life/personal/books/computing/programmers-math.md"};function n(l,t,d,s,p,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="程序员的数学" tabindex="-1">程序员的数学 <a class="header-anchor" href="#程序员的数学" aria-label="Permalink to &quot;程序员的数学&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 数据结构、算法与软件设计</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>本页以结城浩的《程序员的数学》为候选书目介绍。它通过日常问题和小型谜题解释编程常用的数学思维，适合希望补足逻辑、计数和证明基础，却暂时不想从高强度公式推导开始的读者。</p><p>重点不是背更多公式，而是理解为什么某种表达能减少遗漏：如何完整划分情况，如何证明循环一直保持某个性质，以及如何通过递归把大问题拆成同类小问题。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p><strong>中文版作者与版次待确认。</strong> 当前书单没有 ISBN；下表依据结城浩官网公开的日文第2版目录整理，共 <strong>9 章主体</strong>，另列附录。官网注明第2版新增机器学习入门附录，因此不能把这一附录自动认定为手中中文版本的内容。中文章名为本站译述。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>本页参考作者为结城浩（Hiroshi Yuki），中文实物版本仍待确认。作者官网列有《数学女孩》、程序员数学、密码技术与程序设计等作品，并公开本书日文第2版目录与勘误。其优势是面向读者解释抽象概念的写作经验，不能据此将本书当作完整的大学数学课程。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合会写条件和循环、却对证明、计数与递归缺少信心的程序员。无需先补完整高等数学；目标为算法理论或机器学习推导的读者，应把它作为思维入门，再进入专题教材。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参考版本章节</th><th>核心内容</th></tr></thead><tbody><tr><td>第1章 0 的故事</td><td>从十进制、二进制与位值制理解 0 的作用，认识表示方法如何影响思考。</td></tr><tr><td>第2章 逻辑</td><td>使用真假、逻辑运算和德摩根定律，讨论分类的穷尽性与互斥性。</td></tr><tr><td>第3章 余数</td><td>从周期与分组问题出发，学习利用余数表达重复规律。</td></tr><tr><td>第4章 数学归纳法</td><td>用基础情形和归纳步骤建立证明，并联系循环不变量。</td></tr><tr><td>第5章 排列与组合</td><td>通过计数法则、排列和组合减少逐项枚举，检查重复计算与遗漏。</td></tr><tr><td>第6章 递归</td><td>用汉诺塔、阶乘和斐波那契数列理解自我定义与终止条件。</td></tr><tr><td>第7章 指数爆炸</td><td>比较指数增长、二分查找和对数，认识规模如何迅速改变问题难度。</td></tr><tr><td>第8章 无法计算的问题</td><td>通过反证、可数性和对角线方法进入停机问题，理解计算能力的边界。</td></tr><tr><td>第9章 程序员的数学是什么</td><td>回顾问题求解中的结构化思考，将数学方法连接到日常编程。</td></tr><tr><td>附录1 迈向机器学习的第一步</td><td>日文第2版增加的入门内容，介绍预测、分类、感知机与学习过程。</td></tr><tr><td>附录2 阅读指南</td><td>提供进一步阅读的方向；实际中文版本的书目与编排需另行核对。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>把“应该如此”写成可以检查的陈述，就是数学进入代码的起点。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>给一个循环写出初始化、每轮保持的性质与结束条件，再用数学归纳法对应这三部分。还可以为权限分支做真假表，检查是否穷尽且互斥；这些动作能直接帮助发现遗漏，而不依赖复杂公式。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>谜题和图示适合降低心理门槛，但不能替代离散数学、概率或线性代数的系统训练。候选日文第2版的机器学习附录只是入门，不应据此期待掌握训练算法；中文是否收录仍需核对。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给“会写代码却怕数学”的读者：先把逻辑和归纳用进一个小程序，兴趣往往来自能解释自己的结果。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li><a href="https://www.hyuki.com/math/" target="_blank" rel="noopener noreferrer">结城浩：日文第2版作者页面与完整目录</a>：9 章及附录结构的主要来源。</li><li>书名来自本次书单；请按中文版权页核对作者、原书版本与附录是否收录，不将系列续作混入本册。</li><li><a href="https://www.hyuki.com/" target="_blank" rel="noopener noreferrer">结城浩个人主页与著作</a>：核对作者写作方向；中文册次和译者仍待实物确认。</li></ul>',26)])])}const m=e(i,[["render",n]]);export{u as __pageData,m as default};
